update inventory
set total_quantity = total_quantity + #{num,jdbcType=INTEGER}, update_time = now()
where id = #{id,jdbcType=BIGINT}

update inventory
set total_quantity = total_quantity - #{num,jdbcType=INTEGER}, update_time = now()
where id = #{id,jdbcType=BIGINT} and number >= #{num,jdbcType=INTEGER}
